#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long n, m;
    cin >> n >> m;
    vector<long long> a(n);
    long long total = 0;
    for (auto &x : a) cin >> x, total += x;
    if (total < m) {
        cout << -1 << "\n";
        return 0;
    }
    sort(a.rbegin(), a.rend());
    a.push_back(0);
    long long answer = 0;
    // Lower the `width` highest stocks together from a[i] down to a[i+1], level by level.
    for (long long i = 0; i < n && m > 0; i++) {
        long long width = i + 1, high = a[i], low = a[i + 1];
        long long take = min(m, (high - low) * width);
        long long levels = take / width, rest = take % width;
        // width*levels <= take <= m keeps the product inside 64 bits.
        answer += width * levels * (2 * high - levels + 1) / 2 + rest * (high - levels);
        m -= take;
    }
    cout << answer << "\n";
}

import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static long next() {
        while (buf[pos] != '-' && (buf[pos] < '0' || buf[pos] > '9')) pos++;
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long x = 0;
        while (pos < buf.length && buf[pos] >= '0' && buf[pos] <= '9') x = x * 10 + (buf[pos++] - '0');
        return neg ? -x : x;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = (int) next();
        long m = next();
        long[] a = new long[n + 1];
        long total = 0;
        for (int i = 0; i < n; i++) total += a[i] = next();
        if (total < m) {
            System.out.println(-1);
            return;
        }
        // Sort descending in a[0..n-1]; a[n] stays 0 as the floor.
        Arrays.sort(a, 0, n);
        for (int i = 0, j = n - 1; i < j; i++, j--) {
            long t = a[i];
            a[i] = a[j];
            a[j] = t;
        }
        long answer = 0;
        // Lower the `width` highest stocks together from a[i] down to a[i+1], level by level.
        for (int i = 0; i < n && m > 0; i++) {
            long width = i + 1, high = a[i], low = a[i + 1];
            long take = Math.min(m, (high - low) * width);
            long levels = take / width, rest = take % width;
            // width*levels <= take <= m keeps the product inside 64 bits.
            answer += width * levels * (2 * high - levels + 1) / 2 + rest * (high - levels);
            m -= take;
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"slices"
)

var data []byte
var pos int

func next() int64 {
	for data[pos] != '-' && (data[pos] < '0' || data[pos] > '9') {
		pos++
	}
	neg := data[pos] == '-'
	if neg {
		pos++
	}
	var x int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		x = x*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -x
	}
	return x
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n, m := int(next()), next()
	a := make([]int64, n, n+1)
	var total int64
	for i := range a {
		a[i] = next()
		total += a[i]
	}
	if total < m {
		fmt.Println(-1)
		return
	}
	slices.Sort(a)
	slices.Reverse(a)
	a = append(a, 0)
	var answer int64
	// Lower the `width` highest stocks together from a[i] down to a[i+1], level by level.
	for i := 0; i < n && m > 0; i++ {
		width, high, low := int64(i+1), a[i], a[i+1]
		take := min(m, (high-low)*width)
		levels, rest := take/width, take%width
		// width*levels <= take <= m keeps the product inside 64 bits.
		answer += width*levels*(2*high-levels+1)/2 + rest*(high-levels)
		m -= take
	}
	fmt.Println(answer)
}
